import {gcjToWgs84} from './coordinates.js';
const RAD=Math.PI/180,R=6371000;
export function distance(a,b){const dlat=(b[1]-a[1])*RAD,dlng=(b[0]-a[0])*RAD;const h=Math.sin(dlat/2)**2+Math.cos(a[1]*RAD)*Math.cos(b[1]*RAD)*Math.sin(dlng/2)**2;return R*2*Math.atan2(Math.sqrt(h),Math.sqrt(1-h));}
export function bearing(a,b){const l=(b[0]-a[0])*RAD,lat=a[1]*RAD,lat2=b[1]*RAD;return(Math.atan2(Math.sin(l)*Math.cos(lat2),Math.cos(lat)*Math.sin(lat2)-Math.sin(lat)*Math.cos(lat2)*Math.cos(l))/RAD+360)%360;}
export function destination(p,heading,meters){const d=meters/R,h=heading*RAD,la=p[1]*RAD,lo=p[0]*RAD;const lat=Math.asin(Math.sin(la)*Math.cos(d)+Math.cos(la)*Math.sin(d)*Math.cos(h)),lng=lo+Math.atan2(Math.sin(h)*Math.sin(d)*Math.cos(la),Math.cos(d)-Math.sin(la)*Math.sin(lat));return[lng/RAD,lat/RAD];}
