for (const route of Object.values(routes)) route.points=route.points.map(gcjToWgs84);
export class FlightController{
 constructor({map,city,onUpdate,onStop,onToast,onWaypoint}){Object.assign(this,{map,city,onUpdate,onStop,onToast,onWaypoint});this.active=false;this.keys=new Set();this.frame=null;this.speed=180;this.paused=false;this.distance=0;this.heading=45;this.altitude=280;this.bank=0;this.position=[121.5,31.24];this.route=null;this.last=0;this.touch={};this.tick=this.tick.bind(this);}
 start(position){this.stop(false);this.active=true;this.position=[...position];this.heading=(this.map.getBearing()+35+360)%360;this.altitude=280;this.distance=0;this.paused=false;this.route=null;this.map.stop();this.map.jumpTo({center:position,zoom:15.4,pitch:52});this.city.flight=this;this.last=0;this.frame=requestAnimationFrame(this.tick);}
 stop(notify=true){if(this.frame)cancelAnimationFrame(this.frame);this.frame=null;this.active=false;this.keys.clear();this.touch={};this.route=null;this.city.flight=null;this.map.triggerRepaint();if(notify)this.onStop?.();}
 setRoute(id){const route=routes[id];if(!route)return;this.route={...route,id,index:1,laps:0};this.position=[...route.points[0]];this.heading=bearing(route.points[0],route.points[1]);this.speed=route.speed;this.altitude=id==='city'||id==='islands'?1200:280;this.distance=0;this.paused=false;this.map.jumpTo({center:this.position,zoom:route.zoom,pitch:50,bearing:-25});this.onToast?.('正在自动游览：'+route.name+'。方向键可随时接管驾驶。');this.onUpdate?.(this);}
 pause(){this.paused=!this.paused;this.onUpdate?.(this);this.map.triggerRepaint();}
 tick(t){if(!this.active)return;const dt=Math.min((t-(this.last||t))/1000,.08);this.last=t;if(!this.paused){let turn=(this.keys.has('ArrowRight')||this.keys.has('d')||this.touch.right?1:0)-(this.keys.has('ArrowLeft')||this.keys.has('a')||this.touch.left?1:0);let climb=(this.keys.has('ArrowUp')||this.keys.has('w')||this.touch.up?1:0)-(this.keys.has('ArrowDown')||this.keys.has('s')||this.touch.down?1:0);if((turn||climb)&&this.route){this.route=null;this.onToast?.('已切换到自由驾驶');}let targetTurn=turn;
 if(this.route){const target=this.route.points[this.route.index],dist=distance(this.position,target),desired=bearing(this.position,target),delta=((desired-this.heading+540)%360)-180;targetTurn=Math.max(-1,Math.min(1,delta/25));if(dist<Math.max(70,this.speed/3.6*1.8)){this.route.index++;if(this.route.index>=this.route.points.length){this.route.index=1;this.route.laps++;this.onToast?.('已完成一圈「'+this.route.name+'」，继续巡游。');}this.onWaypoint?.(this.route);}}
 this.heading=(this.heading+targetTurn*42*dt+360)%360;this.bank+=(targetTurn-this.bank)*Math.min(dt*4,1);this.altitude=Math.max(80,Math.min(2500,this.altitude+climb*180*dt));let travel=this.speed/3.6*dt;let next=destination(this.position,this.heading,travel);if(next[0]<120.8||next[0]>122.25||next[1]<30.62||next[1]>31.95){this.heading=(this.heading+180)%360;next=destination(this.position,this.heading,travel);this.onToast?.('已到达上海周边，正在掉头返回。');}this.position=next;this.distance+=travel;
 // Keep the aircraft comfortably in frame without tying the map bearing to its turns.
 this.map.setCenter(destination(this.position,this.map.getBearing(),this.altitude*Math.tan(this.map.getPitch()*Math.PI/180)));this.map.triggerRepaint();}
 if(!this.uiLast||t-this.uiLast>160){this.onUpdate?.(this);this.uiLast=t;}this.frame=requestAnimationFrame(this.tick);}
}
